-- Attach the stable Library V15 sense IDs to the four DEMO_READING lessons.
-- Vocabulary remains supplemental lesson content; Learning ignores it for completion and evidence.

INSERT INTO lesson_blocks (id, lesson_id, sort_order, block_type)
SELECT target.block_id::uuid,
       lesson.id,
       COALESCE((SELECT MIN(existing.sort_order) - 1
                 FROM lesson_blocks existing
                 WHERE existing.lesson_id = lesson.id), 0),
       'VOCABULARY'
FROM (VALUES
    ('L1', '7c000000-0000-4000-8000-000000000001'),
    ('L2', '7c000000-0000-4000-8000-000000000002'),
    ('L3', '7c000000-0000-4000-8000-000000000003'),
    ('L4', '7c000000-0000-4000-8000-000000000004')
) AS target(lesson_code, block_id)
JOIN lessons lesson ON lesson.code = target.lesson_code AND lesson.status = 'PUBLISHED'
JOIN topics topic ON topic.id = lesson.topic_id AND topic.code = 'DEMO_READING'
ON CONFLICT (id) DO NOTHING;

INSERT INTO lesson_block_vocabulary (block_id, vocabulary_sense_id, sort_order)
SELECT block.id, target.sense_id::uuid, target.sense_sort_order
FROM (VALUES
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000001', 1),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000002', 2),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000003', 3),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000004', 4),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000005', 5),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000006', 6),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000007', 7),
    ('L1', '7c000000-0000-4000-8000-000000000001', '7a000000-0000-4000-8000-000000000008', 8),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000009', 1),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000010', 2),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000011', 3),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000012', 4),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000013', 5),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000014', 6),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000015', 7),
    ('L2', '7c000000-0000-4000-8000-000000000002', '7a000000-0000-4000-8000-000000000016', 8),
    ('L3', '7c000000-0000-4000-8000-000000000003', '7a000000-0000-4000-8000-000000000017', 1),
    ('L3', '7c000000-0000-4000-8000-000000000003', '7a000000-0000-4000-8000-000000000018', 2),
    ('L3', '7c000000-0000-4000-8000-000000000003', '7a000000-0000-4000-8000-000000000019', 3),
    ('L3', '7c000000-0000-4000-8000-000000000003', '7a000000-0000-4000-8000-000000000020', 4),
